1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const sum = (amounts: number[]): number =>
23	  amounts.reduce((total, amount) => total + amount, 0);
24	
25	const PROCESSING_FEE = 5;
26	
27	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
28	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
29	const roundUpInMHPCOsFavour = (amount: number): number =>
30	  Math.ceil(Number(amount.toFixed(6)));
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
42	
43	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const COMPONENT_BLOCK_SIZE = 3;
46	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
47	
48	const groupByType = (items: Item[]): Item[][] => {
49	  const groups = new Map<string, Item[]>();
50	
51	  for (const item of items) {
52	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
53	  }
54	
55	  return [...groups.values()];
56	};
57	
58	// A block is a special price for exactly 3 items of one type; any other count
59	// is charged per item.
60	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
61	  alikeItems.length === COMPONENT_BLOCK_SIZE
62	    ? COMPONENT_BLOCK_BASE_PREMIUM
63	    : sum(alikeItems.map(basePremiumOf));
64	
65	const policyBasePremiumOf = (items: Item[]): number =>
66	  sum(groupByType(items).map(alikeGroupBasePremiumOf));
67	
68	const quote = (step: QuoteStep): number => {
69	  const policyBasePremium = policyBasePremiumOf(step.items);
70	  const firstInsuranceSurcharge =
71	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
72	
73	  return roundUpInMHPCOsFavour(
74	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
75	  );
76	};
77	
78	export const runScenario = (scenario: Scenario): ScenarioResults => {
79	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
80	};
